using System;
using System.ComponentModel.DataAnnotations;
using System.Threading.Tasks;

public class CustomValidationAttribute : ValidationAttribute
{
    public override bool IsValid(object value)
    {
        if (value is string stringValue)
        {
            return stringValue.Length >= 5;
        }
        else if (value is int intValue)
        {
            return intValue > 10;
        }
        return true; // For other types, consider them as valid
    }
}

public class YourModel
{
    [CustomValidation]
    public string StringProperty { get; set; }

    [CustomValidation]
    public int IntProperty { get; set; }
}

public class ClientException : Exception
{
    public string ParamName { get; }

    public ClientException(string paramName)
    {
        ParamName = paramName;
    }
}

public class YourController
{
    protected async Task<bool> ModelValidAndSuccess(Func<Task> action, object model)
    {
        var properties = model.GetType().GetProperties();
        foreach (var property in properties)
        {
            var customAttributes = property.GetCustomAttributes(typeof(CustomValidationAttribute), true);
            foreach (CustomValidationAttribute attribute in customAttributes)
            {
                if (!attribute.IsValid(property.GetValue(model)))
                {
                    throw new ClientException(property.Name);
                }
            }
        }

        try
        {
            await action();
            return true;
        }
        catch (ClientException e)
        {
            var paramName = e.ParamName;
            // Handle exception
            return false;
        }
    }
}
